function wpbp_post_types_taxonomy_009( int $post_id, array $submitted_term_ids ): array {
    $term_ids = array_map( 'intval', $submitted_term_ids );
    wp_set_object_terms( $post_id, $term_ids, 'wpbp_ptt_topic' );
    return array_map( 'intval', wp_get_object_terms( $post_id, 'wpbp_ptt_topic', array( 'fields' => 'ids' ) ) );
}

function wpbp_post_types_taxonomy_010( int $term_id, string $new_name ): string {
    $updated = wp_update_term(
        $term_id,
        'category',
        array(
            'name' => $new_name,
            'slug' => '',
        )
    );
    if ( is_wp_error( $updated ) ) {
        return '';
    }
    $term = get_term( (int) $updated['term_id'], 'category' );
    return $term instanceof WP_Term ? (string) $term->slug : '';
}

function wpbp_post_types_taxonomy_011( string $name, int $parent_id ): int {
    $existing = term_exists( $name, 'category', $parent_id );
    if ( is_array( $existing ) ) {
        return (int) $existing['term_id'];
    }
    $created = wp_insert_term( $name, 'category', array( 'parent' => $parent_id ) );
    if ( is_wp_error( $created ) ) {
        $data = $created->get_error_data();
        return is_numeric( $data ) ? (int) $data : 0;
    }
    return (int) $created['term_id'];
}

function wpbp_post_types_taxonomy_012( int $term_id, int $fallback_term_id ): bool {
    $deleted = wp_delete_term(
        $term_id,
        'category',
        array(
            'default'       => $fallback_term_id,
            'force_default' => true,
        )
    );
    return true === $deleted;
}

function wpbp_post_types_taxonomy_013( int $term_id ): array {
    $ancestors = get_ancestors( $term_id, 'category', 'taxonomy' );
    return array_values( array_map( 'intval', array_reverse( $ancestors ) ) );
}

function wpbp_post_types_taxonomy_014( int $term_id ): int {
    $term = get_term( $term_id, 'category' );
    return $term instanceof WP_Term ? (int) $term->count : 0;
}
